fn average(values: &[i32]) -> i32 {
    if values.is_empty() {
        return 0;
    }
    let mut sum = 0;
    for value in values {
        sum += *value;
    }
    sum / values.len() as i32
}

fn greeting() -> &'static str {
    "hello"
}

fn main() {
    println!("{}", average(&[1, 2, 3]));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn greeting_is_stable() {
        assert_eq!(greeting(), "hello");
    }
}
